package main

import (
    "fmt"
    "time"
)

func fetchData(id int) {
    time.Sleep(100 * time.Millisecond) // simulate work
    fmt.Printf("Fetched data for ID %d\n", id)
}

func main() {
    // Launch 1000 goroutines — trivial cost
    for i := 0; i < 1000; i++ {
        go fetchData(i)
    }

    // Wait for goroutines (use sync.WaitGroup in real code)
    time.Sleep(time.Second)
}

// Unbuffered channel — synchronizes sender and receiver
func main() {
    messages := make(chan string)

    go func() {
        messages <- "hello"  // send (blocks until received)
    }()

    msg := <-messages  // receive (blocks until sent)
    fmt.Println(msg)   // "hello"
}

// Buffered channel — producer/consumer
func process(jobs <-chan int, results chan<- int) {
    for job := range jobs {
        results <- job * 2
    }
}

func main() {
    jobs := make(chan int, 100)
    results := make(chan int, 100)

    // Start 3 workers
    for w := 0; w < 3; w++ {
        go process(jobs, results)
    }

    // Send 5 jobs
    for j := 0; j < 5; j++ {
        jobs <- j
    }
    close(jobs)
}

func worker(ctx context.Context, jobs <-chan int) {
    for {
        select {
        case job := <-jobs:
            fmt.Printf("Processing job %d\n", job)

        case <-ctx.Done():
            fmt.Println("Worker cancelled")
            return

        case <-time.After(5 * time.Second):
            fmt.Println("No jobs for 5s, idling...")
        }
    }
}

// Fan-in: merge two channels into one
func merge(ch1, ch2 <-chan string) <-chan string {
    out := make(chan string)
    go func() {
        defer close(out)
        for ch1 != nil || ch2 != nil {
            select {
            case v, ok := <-ch1:
                if !ok { ch1 = nil; continue }
                out <- v
            case v, ok := <-ch2:
                if !ok { ch2 = nil; continue }
                out <- v
            }
        }
    }()
    return out
}
